import json
import re
from docx import Document

def fill_template(template_path, data_path, output_path):
    # Load data
    with open(data_path) as f:
        data = json.load(f)

    # Load template
    doc = Document(template_path)

    should_relocate = data.get('RELOCATION_PACKAGE') == 'Yes'

    def replace_placeholders(text):
        pattern = r'\{\{([A-Z_0-9]+)\}\}'
        new_text = text
        for match in re.finditer(pattern, text):
            key = match.group(1)
            placeholder = match.group(0)
            if key in data:
                new_text = new_text.replace(placeholder, str(data[key]))
        return new_text

    # Handle conditional section
    start_marker = '{{IF_RELOCATION}}'
    end_marker = '{{END_IF_RELOCATION}}'

    in_conditional = False
    paras_to_delete = []

    # First pass: Handle markers and placeholders
    for para in doc.paragraphs:
        text = para.text

        if start_marker in text and end_marker in text:
            if should_relocate:
                new_text = text.replace(start_marker, '').replace(end_marker, '')
                new_text = replace_placeholders(new_text)
                para.text = new_text
            else:
                para.text = ''
            continue

        if start_marker in text:
            in_conditional = True
            if should_relocate:
                para.text = text.replace(start_marker, '')
                para.text = replace_placeholders(para.text)
            else:
                para.text = ''
                paras_to_delete.append(para)
            continue

        if end_marker in text:
            in_conditional = False
            if should_relocate:
                para.text = text.replace(end_marker, '')
                para.text = replace_placeholders(para.text)
            else:
                para.text = ''
                paras_to_delete.append(para)
            continue

        if in_conditional:
            if should_relocate:
                para.text = replace_placeholders(para.text)
            else:
                para.text = ''
                paras_to_delete.append(para)
        else:
            para.text = replace_placeholders(para.text)

    # Process tables
    def process_table(table):
        for row in table.rows:
            for cell in row.cells:
                for para in cell.paragraphs:
                    # Note: We don't handle cross-paragraph conditionals in tables 
                    # as it's much rarer and more complex.
                    para.text = replace_placeholders(para.text)
                for nested in cell.tables:
                    process_table(nested)

    for table in doc.tables:
        process_table(table)

    # Headers/Footers
    for section in doc.sections:
        for para in section.header.paragraphs:
            para.text = replace_placeholders(para.text)
        for para in section.footer.paragraphs:
            para.text = replace_placeholders(para.text)

    doc.save(output_path)

if __name__ == "__main__":
    fill_template('offer_letter_template.docx', 'employee_data.json', 'offer_letter_filled.docx')

